def comprimir_repeticiones(texto: str) -> str:
    if not texto:
        return ""
    resultado = []
    actual = texto[0]
    contador = 1
    for caracter in texto[1:]:
        if caracter == actual:
            contador += 1
        else:
            resultado.append(actual + str(contador))
            actual = caracter
            contador = 1
    # Añadir el último grupo
    resultado.append(actual + str(contador))
    return "".join(resultado)

import csv
from io import StringIO

def parsear_ventas(texto: str) -> list[dict]:
    # Si el texto está vacío o solo contiene espacios, devolver lista vacía
    if not texto or texto.strip() == '':
        return []

    lines = texto.splitlines()

    # Buscar la primera línea no vacía como cabecera
    header_line = None
    for line in lines:
        if line.strip():
            header_line = line
            break

    if header_line is None:
        return []  # No hay cabecera

    # Parsear la cabecera
    header_reader = csv.reader(StringIO(header_line))
    try:
        header = next(header_reader)
    except StopIteration:
        return []

    expected_header = ["fecha", "producto", "cantidad", "precio"]
    if header != expected_header:
        raise ValueError("Cabecera incorrecta")

    result = []
    for line in lines:
        stripped = line.strip()
        if not stripped:
            continue  # Ignorar líneas vacías o con solo espacios

        # Parsear la fila
        row_reader = csv.reader([line])
        try:
            fields = next(row_reader)
        except StopIteration:
            raise ValueError("Fila vacía")

        if len(fields) != 4:
            raise ValueError("Número de campos incorrecto")

        fecha = fields[0].strip()
        producto = fields[1].strip()
        cantidad_str = fields[2].strip()
        precio_str = fields[3].strip()

        # Validar cantidad
        try:
            cantidad = int(cantidad_str)
        except ValueError:
            raise ValueError("Cantidad no es un entero")
        if cantidad < 0:
            raise ValueError("Cantidad negativa")

        # Validar precio
        try:
            precio = float(precio_str)
        except ValueError:
            raise ValueError("Precio no es un número")

        result.append({
            "fecha": fecha,
            "producto": producto,
            "cantidad": cantidad,
            "precio": precio
        })

    return result

def promedio_movil(valores: list[float], ventana: int) -> list[float]:
    if ventana <= 0 or ventana > len(valores):
        return []
    resultado = []
    for i in range(len(valores) - ventana + 1):
        resultado.append(sum(valores[i:i + ventana]) / ventana)
    return resultado

from collections import OrderedDict


class CacheLRU:
    def __init__(self, capacidad: int):
        if capacidad < 0:
            raise ValueError("La capacidad no puede ser negativa")
        self.capacidad = capacidad
        self._datos = OrderedDict()

    def get(self, clave):
        if clave not in self._datos:
            return None
        # Marcar como usada recientemente
        self._datos.move_to_end(clave)
        return self._datos[clave]

    def put(self, clave, valor):
        if self.capacidad == 0:
            # No se puede almacenar nada
            return
        if clave in self._datos:
            # Actualizar y mover al final (más reciente)
            self._datos[clave] = valor
            self._datos.move_to_end(clave)
        else:
            # Si la caché está llena, descartar la más antigua
            if len(self._datos) >= self.capacidad:
                self._datos.popitem(last=False)
            self._datos[clave] = valor

    def __len__(self):
        return len(self._datos)
